#!/usr/bin/env node
/**
 * Writes oidc-tokens.json: JWKS documents and tokens shaped like Zitadel's
 * access tokens, for the weldsuite-auth OIDC tests.
 *
 *   node rust/crates/auth/tests/fixtures/generate-oidc-tokens.mjs
 *
 * The private keys live only in memory while this runs, so the fixture holds
 * nothing secret. Every run makes new keys: rerun it and commit the JSON
 * whenever a case is added. Times are fixed around NOW; the tests pass NOW to
 * the verifier, except `longLived`, which middleware tests (real clock) use.
 */
import { generateKeyPairSync, sign } from 'node:crypto';
import { writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const NOW = 1_800_000_000;
const ISSUER = 'https://auth.example.test';
const PROJECT = '300000000000000100';
const CLIENT = '300000000000000200@weldsuite';
const ORG = '300000000000000001';
const USER = '300000000000000042';
const ORG_CLAIM = 'urn:zitadel:iam:org:id';

const rsa = () => generateKeyPairSync('rsa', { modulusLength: 2048 });
const keyA = rsa();
const keyB = rsa();
const unpublished = rsa();
const keyEc = generateKeyPairSync('ec', { namedCurve: 'P-256' });
const encKey = rsa();

const jwk = (pair, kid, alg, use = 'sig') => ({
  ...pair.publicKey.export({ format: 'jwk' }),
  kid,
  alg,
  use,
});

const b64 = (value) =>
  Buffer.from(typeof value === 'string' ? value : JSON.stringify(value)).toString('base64url');

function jwt(payload, { key = keyA.privateKey, header = {}, alg = 'RS256' } = {}) {
  const head = b64({ alg, typ: 'JWT', kid: 'key-a', ...header });
  const body = b64(payload);
  const input = Buffer.from(`${head}.${body}`);
  let signature;
  if (alg === 'ES256') {
    signature = sign('sha256', input, { key, dsaEncoding: 'ieee-p1363' });
  } else if (alg === 'none') {
    signature = Buffer.alloc(0);
  } else {
    signature = sign('sha256', input, key);
  }
  return `${head}.${body}.${signature.toString('base64url')}`;
}

const base = {
  iss: ISSUER,
  sub: USER,
  aud: [PROJECT, CLIENT],
  client_id: CLIENT,
  sid: 'V1_300000000000000777',
  auth_time: NOW - 600,
  amr: ['pwd', 'otp', 'mfa'],
  [ORG_CLAIM]: ORG,
  iat: NOW - 60,
  nbf: NOW - 60,
  exp: NOW + 3600,
};
const without = (...names) =>
  Object.fromEntries(Object.entries(base).filter(([name]) => !names.includes(name)));

const tokens = {
  valid: jwt(base),
  rotated: jwt(base, { key: keyB.privateKey, header: { kid: 'key-b' } }),
  ec: jwt(base, { key: keyEc.privateKey, alg: 'ES256', header: { kid: 'key-ec' } }),
  atJwt: jwt(base, { header: { typ: 'at+jwt' } }),
  noKid: jwt(base, { header: { kid: undefined } }),
  audString: jwt({ ...base, aud: PROJECT }),
  wrongIssuer: jwt({ ...base, iss: 'https://auth.other.test' }),
  issuerWithSlash: jwt({ ...base, iss: `${ISSUER}/` }),
  wrongAudience: jwt({ ...base, aud: ['another-project'] }),
  noAudience: jwt(without('aud')),
  expired: jwt({ ...base, exp: NOW - 60 }),
  expiredWithinSkew: jwt({ ...base, exp: NOW - 20 }),
  noExp: jwt(without('exp')),
  notYetValid: jwt({ ...base, nbf: NOW + 120 }),
  noSub: jwt(without('sub')),
  emptySub: jwt({ ...base, sub: '' }),
  noOrg: jwt(without(ORG_CLAIM)),
  rolesClaim: jwt({
    ...without(ORG_CLAIM),
    'urn:zitadel:iam:org:project:roles': {
      admin: { [ORG]: 'acme.auth.example.test' },
      member: { [ORG]: 'acme.auth.example.test' },
    },
  }),
  noSid: jwt(without('sid')),
  passwordOnly: jwt({ ...base, amr: ['pwd'] }),
  noAuthTime: jwt(without('auth_time')),
  otherKey: jwt(base, { key: unpublished.privateKey }),
  unknownKid: jwt(base, { header: { kid: 'key-z' } }),
  wrongTyp: jwt(base, { header: { typ: 'JOSE+JSON' } }),
  algNone: jwt(base, { alg: 'none' }),
  // An RS256 token naming the EC key: the key's declared alg is ES256.
  algMismatch: jwt(base, { header: { kid: 'key-ec' } }),
  // Signed with the public key's PEM as an HMAC secret: the classic confusion.
  hs256: (() => {
    const head = b64({ alg: 'HS256', typ: 'JWT', kid: 'key-a' });
    const body = b64(base);
    return `${head}.${body}.${b64('not-a-signature')}`;
  })(),
  malformed: 'not.a.jwt',
  longLived: jwt({ ...base, iat: 1_700_000_000, nbf: 1_700_000_000, auth_time: 1_700_000_000, exp: 4_000_000_000 }),
};

const fixture = {
  note: 'Generated by generate-oidc-tokens.mjs; public keys only.',
  now: NOW,
  issuer: ISSUER,
  project: PROJECT,
  client: CLIENT,
  org: ORG,
  user: USER,
  jwks: { keys: [jwk(keyA, 'key-a', 'RS256')] },
  jwksRotated: { keys: [jwk(keyA, 'key-a', 'RS256'), jwk(keyB, 'key-b', 'RS256')] },
  jwksMixed: {
    keys: [
      jwk(keyA, 'key-a', 'RS256'),
      jwk(keyEc, 'key-ec', 'ES256'),
      jwk(encKey, 'key-enc', 'RSA-OAEP-256', 'enc'),
      { kty: 'oct', kid: 'key-oct', k: b64('a shared secret') },
    ],
  },
  tokens,
};

const out = path.join(path.dirname(fileURLToPath(import.meta.url)), 'oidc-tokens.json');
writeFileSync(out, `${JSON.stringify(fixture, null, 2)}\n`);
console.log(`wrote ${out}`);
